<template>
  <view class="bottom-tab-container">
    <view class="tab-item" :class="{ active: activeTab === 'asset' }" @click="switchTab('asset')">
      <view class="tab-icon">资产</view>
    </view>
    <view class="tab-item add-btn" @click="addItem">
      <view class="add-icon">+</view>
    </view>
    <view class="tab-item" :class="{ active: activeTab === 'wardrobe' }" @click="switchTab('wardrobe')">
      <view class="tab-icon">服饰</view>
    </view>
  </view>

  <!-- 弹窗组件 -->
  <uni-popup ref="popup" type="bottom" @change="onPopupChange">
    <view class="popup-content">
      <!-- 弹窗头部 -->
      <view class="popup-header">
        <view class="popup-close" @click="closePopup">
          <image class="popup-close-icon" src="@/static/icon/cancel.svg" />
        </view>
        <text class="popup-title">新增资产</text>
        <view class="submit-btn" @click="submitForm">
          <image class="popup-submit-icon" src="@/static/icon/check.svg" />
        </view>
      </view>
      <!-- 资产表单：直接引入封装好的组件 -->
      <view class="popup-body">
        <AssetAddForm />
      </view>
    </view>
  </uni-popup>
</template>

<script setup>
import { ref, onMounted } from 'vue';
import AssetAddForm from '@/components/asset/AssetAddForm.vue'
// 将activeTab定义为响应式变量
const activeTab = ref('asset');

const popup = ref(null); // 弹窗实例

// 点击加号触发弹窗
function addItem() {
  console.log('点击加号')
  showPopup();
}
// 显示弹窗：通过 ref 调用 open 方法
function showPopup() {
  if (popup.value) {
    popup.value.open(); // 直接调用组件内置方法
    console.log('弹窗已触发打开'); // 新增日志，验证是否执行
  } else {
    console.error('弹窗实例获取失败');
  }
}
// 关闭弹窗：通过 ref 调用 close 方法
function closePopup() {
  if (popup.value) {
    popup.value.close();
  }
}
// 提交表单
function submitForm() {
  console.log('提交表单')
  // 成功之后关闭表单，这里后续要验证是否成功才能关闭
  closePopup();
}
// 监听弹窗状态变化
function onPopupChange(e) {
  console.log('弹窗状态变化：', e.show); // 新增日志，查看弹窗状态
  // 无需再手动调用 closePopup，e.show 为 false 时弹窗已自动关闭
}

// 获取当前页面路由，初始化activeTab状态
onMounted(() => {
  const pages = getCurrentPages();
  const currentPage = pages[pages.length - 1];
  if (currentPage) {
    const route = currentPage.route || '';
    activeTab.value = route.includes('wardrobe') ? 'wardrobe' : 'asset';
  }
});

function switchTab(tabName) {
  // 更新activeTab状态
  activeTab.value = tabName;
  
  if (tabName === 'asset') {
    uni.navigateTo({
      url: '/pages/asset/list/list'
    });
  } else if (tabName === 'wardrobe') {
    uni.navigateTo({
      url: '/pages/wardrobe/list/list'
    });
  }
}

</script>

